const root=process.cwd(), disk=statfsSync(root);
assert(disk.bavail*disk.bsize>=1073741824);
const storage=createOwnedTestDirectory('memory-maintenance-fence-');
const prior=JSON.parse(readFileSync('.git/q100-artifact-probe.json','utf8'));
const installed=prior.artifact.installedRoot;
const entries={installed:join(installed,'dist/presentation/cli/index.js'),'current-source':resolve('src/presentation/cli/index.ts')};
const sha=(value:Buffer|string)=>createHash('sha256').update(value).digest('hex');
function verifyInputs(){
 for(const file of prior.artifact.files)assert.equal(sha(readFileSync(join(installed,file.path))),file.sha256,file.path);
 for(const file of prior.sourceInputs)assert.equal(sourceHash(readFileSync(file.path,'utf8')),file.sourceHash,file.path);
}
function env(home:string){return {...process.env,HOME:home,USERPROFILE:home,XDG_DATA_HOME:join(home,'data'),XDG_CONFIG_HOME:join(home,'config'),MEMORY_HOME:join(home,'authored'),CLAUDE_CONFIG_DIR:join(home,'claude'),TEMP:home,TMP:home,TMPDIR:home};}
function run(entry:string,home:string,args:string[]){const command=[process.execPath,entry,...args],r=Bun.spawnSync(command,{cwd:home,env:env(home),stdout:'pipe',stderr:'pipe',timeout:30000});return {command,exit:r.exitCode,output:new TextDecoder().decode(r.stdout)+new TextDecoder().decode(r.stderr)};}
function seedDb(path:string,uuid='existing'){const db=new OwnedDatabase(path);try{createSchema(db);db.run("INSERT INTO facts(uuid,type,project,content,observed_at) VALUES(?,'learning','synthetic','synthetic fixture','2026-09-28T10:00:00.000Z')",[uuid]);}finally{db.close();}}
const report:any={recordedAt:new Date().toISOString(),runtime:Bun.version,startingRevision:'a4b44b78e2de030b8732568e5da3e810f0fc1b33',runs:[]};
try{
 verifyInputs();
 const donor=join(storage.dir,'donor'),donorData=join(donor,'data','memory');mkdirSync(join(donorData,'events'),{recursive:true});seedDb(join(donorData,'memory.db'),'donor-fact');
 writeFileSync(join(donorData,'events','events-synthetic.jsonl'),'');
 const backup=run(entries['current-source'],donor,['backup','create','--json']);report.donorBackup=backup;assert.equal(backup.exit,0);
 const backupPath=JSON.parse(backup.output).data.backupPath;assert(backupPath.startsWith(storage.dir));
 for(const mode of ['event-fence','paired-fence'])for(const reader of ['installed','current-source'] as const)for(const action of ['backup','restore','verify'] as const){
  const home=join(storage.dir,mode+'-'+reader+'-'+action),data=join(home,'data','memory');mkdirSync(data,{recursive:true});
  const dbPath=join(data,'memory.db'),events=join(data,'events');
  if(mode==='paired-fence')mkdirSync(dbPath);else seedDb(dbPath);
  writeFileSync(events,'Synthetic legacy event fence.');
  const before=mode==='event-fence'?sha(readFileSync(dbPath)):null;
  const args=action==='backup'?['backup','create','--json']:action==='restore'?['restore',backupPath,'--confirm','--json']:['projections','rebuild','--verify','--json'];
  const execution=run(entries[reader],home,args);
  const databaseFenceIntact=lstatSync(dbPath).isDirectory(),eventFenceIntact=lstatSync(events).isFile()&&readFileSync(events,'utf8')==='Synthetic legacy event fence.';
  let facts=null;if(!databaseFenceIntact){const db=new OwnedDatabase(dbPath);try{using statement=db.prepare('SELECT uuid FROM facts ORDER BY uuid');facts=statement.all();}finally{db.close();}}
  report.runs.push({reader,mode,action,execution,databaseFenceIntact,eventFenceIntact,facts,databaseByteHashBefore:before,databaseByteHashAfter:databaseFenceIntact?null:sha(readFileSync(dbPath))});
 }
