finally{report.source=readFileSync(import.meta.path,'utf8');writeFileSync('.git/q100-maintenance-fence.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({status:report.status,error:report.error,inputsUnchanged:report.inputsUnchanged,runs:report.runs.map((row:any)=>({...row,execution:{exit:row.execution.exit,output:row.execution.output}}))}));storage.cleanup();}

